    "usageCode": "import { ElasticWaveText } from \"@/components/ui/elastic-wave-text\";\n\nexport function Example() {\n  return (\n    <ElasticWaveText text=\"Harmonic Transverse Wave\" amplitude={-14} />\n  );\n}",
