    "usageCode": "import { ExpandableBentoCard } from \"@/components/ui/expandable-bento-card\";\n\nexport function Example() {\n  return (\n    <ExpandableBentoCard\n      badge=\"RUNTIME_TELEMETRY\"\n      title=\"GPU Compositor Pipeline\"\n    />\n  );\n}",
