    "usageCode": "import { FloatingCompassNav } from \"@/components/ui/floating-compass-nav\";\n\nexport function Example() {\n  return (\n    <FloatingCompassNav defaultQuadrant=\"SE\" stiffness={300} damping={24} />\n  );\n}",
