    "usageCode": "import { KineticRollingCounter } from \"@/components/ui/kinetic-rolling-counter\";\n\nexport function Example() {\n  return (\n    <KineticRollingCounter defaultValue={1248} step={17} stiffness={340} damping={26} />\n  );\n}",
