    "usageCode": "import { KineticSlider } from \"@/components/ui/kinetic-slider\";\n\nexport function Example() {\n  return (\n    <KineticSlider\n      label=\"Spring Stiffness\"\n      defaultValue={72}\n      min={0}\n      max={100}\n      unit=\"%\"\n    />\n  );\n}",
