    "usageCode": "import { VariableProximityText } from \"@/components/ui/variable-proximity-text\";\n\nexport function Example() {\n  return (\n    <VariableProximityText\n      text=\"Engineered with Hooke's Law spring physics.\"\n      radius={120}\n      maxLift={-10}\n      maxScale={1.22}\n    />\n  );\n}",
